local _k={211,207,88,146,62,245,68,56,8,61,52,180,112,206,121,171}
local _b="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local _m={}
for i=1,#_b do _m[_b:sub(i,i)]=i-1 end
local function _d(s)
    s=s:gsub("[^A-Za-z0-9+/=]","")
    local o={}
    for i=1,#s,4 do
        local a=_m[s:sub(i,i)] or 0
        local b=_m[s:sub(i+1,i+1)] or 0
        local c=_m[s:sub(i+2,i+2)] or 0
        local d=_m[s:sub(i+3,i+3)] or 0
        local n=a*262144+b*4096+c*64+d
        o[#o+1]=string.char(math.floor(n/65536)%256)
        if s:sub(i+2,i+2)~="=" then o[#o+1]=string.char(math.floor(n/256)%256) end
        if s:sub(i+3,i+3)~="=" then o[#o+1]=string.char(n%256) end
    end
    return table.concat(o)
end
local _p=table.concat(_c)
local _r=_d(_p)
